code.cpp:
class Solution {
public:
    ListNode* modifiedList(vector<int>& nums, ListNode* head) {
        bool bad[100001] = {false};
        for (int x : nums) bad[x] = true;
        ListNode dummy(0, head);
        ListNode* curr = &dummy;
        while (curr->next) {
            if (bad[curr->next->val]) {
                curr->next = curr->next->next;
            } else {
                curr = curr->next;
            }
        }
        return dummy.next;
    }
};
